// Illustrative stock adjustment use case; tables/models belong to the project.
return DB::transaction(function () use ($productId, $delta, $actorId) {
    $stock = Stock::where('product_id', $productId)->lockForUpdate()->firstOrFail();
    if ($stock->quantity + $delta < 0) {
        throw new InsufficientStock;
    }
    $stock->movements()->create(['delta' => $delta, 'actor_id' => $actorId]);
    $stock->update(['quantity' => $stock->quantity + $delta]);
    return $stock->fresh();
});

